static int sctp_stream_alloc_in(struct sctp_stream *stream, __u16 incnt,
				gfp_t gfp)
{
	int ret;

	if (incnt <= stream->incnt)
		return 0;

	ret = genradix_prealloc(&stream->in, incnt, gfp);
